import { CLI_TELEMETRY_SYMBOL, noopLogger, setCliTelemetry } from '@sanity/cli-core/telemetry';
const PACKAGE_NAME = '@sanity/runtime-cli';
/**
 * Registers a no-op telemetry store so `getCliTelemetry()` calls don't warn.
 */
const hook = async ({ config }) => {
    if (config.name !== PACKAGE_NAME)
        return;
    if (globalThis[CLI_TELEMETRY_SYMBOL])
        return;
    setCliTelemetry(noopLogger);
};
export default hook;
